import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1788270838000}`),a={name:`guide/getting-started.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><ul><li><strong>Node.js ≥ 22</strong> (or Docker, if you prefer the container)</li><li>A <strong>Hetzner Cloud API token</strong> for the project that holds your DNS zones</li></ul><h2 id="_1-create-the-api-token" tabindex="-1">1. Create the API token <a class="header-anchor" href="#_1-create-the-api-token" aria-label="Permalink to “1. Create the API token”">​</a></h2><ol><li>Open the <a href="https://console.hetzner.com" target="_blank" rel="noreferrer">Hetzner Cloud Console</a> and pick the project whose zones you want to manage.</li><li>Go to <strong>Security → API tokens → Generate API token</strong>.</li><li>Choose <strong>Read &amp; Write</strong> for the full tool set, or <strong>Read</strong> if you only want the query tools.</li><li>Copy the token — the console shows it exactly once.</li></ol><div class="danger custom-block"><p class="custom-block-title">Not a DNS Console token</p><p>Tokens from the old DNS Console at <code>dns.hetzner.com</code> do <strong>not</strong> work. That API was shut down in May 2026. The token you need starts life in the Cloud Console under a project, not in the DNS Console.</p></div><div class="tip custom-block"><p class="custom-block-title">Give it its own project</p><p>The token can reach everything in its project, and this server has no way to narrow that. A project containing only the zones you want managed is the cheapest way to limit the blast radius.</p></div><h2 id="_2-connect-it" tabindex="-1">2. Connect it <a class="header-anchor" href="#_2-connect-it" aria-label="Permalink to “2. Connect it”">​</a></h2><p>The shortest path, for Claude Code:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">claude</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> mcp</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> add</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> hetzner-dns</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -s</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> user</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  -e</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> HETZNER_API_TOKEN=your-token</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  --</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> hetzner-dns-mcp</span></span></code></pre></div><p>For Claude Desktop, Codex, the MCP Inspector or Docker, see <a href="/guide/clients">Connecting clients</a>.</p><h2 id="_3-check-that-it-works" tabindex="-1">3. Check that it works <a class="header-anchor" href="#_3-check-that-it-works" aria-label="Permalink to “3. Check that it works”">​</a></h2><p>Ask the assistant to list your zones. It should call <code>list_zones</code> and come back with names, modes and record counts. If it comes back with an error instead:</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th></tr></thead><tbody><tr><td><code>missing required environment variable HETZNER_API_TOKEN</code></td><td>The <code>env</code> block did not reach the process</td></tr><tr><td><code>HTTP 401</code></td><td>Wrong token, or a token from the old DNS Console</td></tr><tr><td><code>HTTP 403</code> on a write</td><td>Read-only token</td></tr><tr><td>Tools do not appear at all</td><td>The client could not start the command — check its MCP log</td></tr></tbody></table><p>The <a href="/guide/faq">FAQ</a> goes through each of these in more detail.</p><h2 id="_4-try-a-change" tabindex="-1">4. Try a change <a class="header-anchor" href="#_4-try-a-change" aria-label="Permalink to “4. Try a change”">​</a></h2><p>Ask for something harmless but real, like adding a TXT record. The first call comes back refused, with a token:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>Refusing to replace the records of RRSet &quot;@/TXT&quot; of zone &quot;example.com&quot; without</span></span>
<span class="line"><span>confirmation. It currently holds 1 record(s), TTL 3600; all of them are replaced</span></span>
<span class="line"><span>by the 2 record(s) in this call. Use get_rrset to review the contents. Confirm</span></span>
<span class="line"><span>with the user, then call set_records again within 5 minutes with confirm_token:</span></span>
<span class="line"><span>&quot;9f3c1a…&quot; and the identical records — the token only works for exactly this list.</span></span></code></pre></div><p>That is the intended flow, not a failure: the assistant should now ask you, and only then call again with the token. If you would rather it never got that far, see <a href="/guide/configuration#read-only-mode">read-only mode</a>.</p><h2 id="running-without-credentials" tabindex="-1">Running without credentials <a class="header-anchor" href="#running-without-credentials" aria-label="Permalink to “Running without credentials”">​</a></h2><p>The server starts, completes the MCP handshake and lists all its tools even with no token set — registries and sandbox inspectors need that. The calls themselves then fail with setup instructions. Nothing reaches the API.</p>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};